			ld b, 40
p_shout_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_shout_si0_e
			inc hl
			inc de
			djnz p_shout_si0
			xor a
			ld (de), a
p_shout_si0_e:
			ld (p_shout_rs), sp
			ld sp, p_shout
			jp ntc_xn
p_shout_r:		; end of shout
			ld de, (p_shout_a0)
			ld hl, var_shout_txt
			dec de
			ld a, (de)		; the destination's capacity
			ld b, a
			inc de
p_shout_so0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_shout_so0_e
			inc hl
			inc de
			djnz p_shout_so0
			xor a
			ld (de), a
p_shout_so0_e:
			ld sp, (p_shout_rs)
			jp ntc_xn
p_findpair_c:		; call findpair (normal)
			pop hl			; target
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_findpair_target), de
			ld hl, 0
			ld (var_findpair_findpair), hl
			ld hl, 0
			ld (var_findpair_x), hl
			ld hl, 0
			ld (var_findpair_y), hl
			ld (p_findpair_rs), sp
			ld sp, p_findpair
			jp ntc_xn
p_findpair_r:		; end of findpair
